import type { ChangeIconRef } from "@/games/wow-forever/types/changes/changeIconRef";
import type { ChangeKind } from "@/games/wow-forever/types/changes/changeKind";
import type { ChangeLink } from "@/games/wow-forever/types/changes/changeLink";
import type { ChangeRow } from "@/games/wow-forever/types/changes/changeRow";

/**
 * One row as `data/changes/*.json` stores it (GENERATED by
 * `python -m scripts.wow_changes.build`; `backend/scripts/wow_changes/entry.py`
 * writes it). Empty fields are left out.
 */
export interface ChangeFileEntry {
  key: string;
  kind: ChangeKind;
  name: string;
  summary: string;
  rows?: readonly ChangeRow[];
  classes?: readonly string[];
  link?: ChangeLink;
  icon?: ChangeIconRef;
  /** Absent = the Forever game files; "seen" = the operator's own client cache; "published" = Blizzard's Game Data API (talents). */
  provenance?: "seen" | "published";
  seenOn?: string;
  /** The client build this row's content first appeared in; null before a second refresh. */
  since: string | null;
}
